function preProcessSVG(svgString: string) {
  const loader = new SVGLoader();
  const data = loader.parse(svgString);
  const lineGeometries: THREE.BufferGeometry[] = [];

  const totalBBox = new THREE.Box3();

  data.paths.forEach((path) => {
    path.subPaths.forEach((subPath) => {
      const points = subPath.getPoints();
      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      geometry.computeBoundingBox();
      if (geometry.boundingBox) totalBBox.union(geometry.boundingBox);
    });
  });

  const size = new THREE.Vector3();
  totalBBox.getSize(size);
  const centerOffset = new THREE.Vector3();
  totalBBox.getCenter(centerOffset);

  const maxDim = Math.max(size.x, size.y);
  const normalizationScale = 1 / (maxDim || 1);

  data.paths.forEach((path) => {
    path.subPaths.forEach((subPath) => {
      const points = subPath.getPoints();
      const geometry = new THREE.BufferGeometry().setFromPoints(points);

      geometry.translate(-centerOffset.x, -centerOffset.y, -centerOffset.z);

      geometry.scale(normalizationScale, normalizationScale, normalizationScale);

      lineGeometries.push(geometry);
    });
  });

  return lineGeometries;
}

export const PROCESSED_CONSTELLATIONS: ProcessedConstellationDefinition[] = Object.entries(
  CONSTELLATIONS
).map(([name, def]) => ({
  name,
  ...def,
  geometries: preProcessSVG(def.svgString),
}));
